pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address manager) public {
        // keep the domain admissible: manager must be a usable address
        vm.assume(manager != address(0));

        // adversarial/config environment: a config contract that grants every role
        // and supports every asset so c's role checks pass when consulted
        MockConfig cfg = new MockConfig();

        // initialization may legitimately fail (contract already initialized);
        // the property is stated over inputs where the flow does not revert
        try c.initialize(address(cfg)) {
            // initialized
        } catch {
            // reference legitimately re-reverting here is admissible; flow aborts
        }

        // drive c through the pause flow as the (possibly role-granted) manager
        vm.prank(manager);
        bool pauseFlowSucceeded;
        try c.pause() {
            pauseFlowSucceeded = true;
        } catch {
            pauseFlowSucceeded = false;
        }

        // GENERAL RULE: whenever the pause flow completes without reverting,
        // the pool's public paused() view must report the true paused state.
        // The mutant always returns false from paused(), so it violates this
        // for any manager address for which the pause flow succeeds.
        assertTrue(!pauseFlowSucceeded || c.paused());
    }
}

