pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    bytes32 constant MANAGER = keccak256("MANAGER");

    function setUp() public { c = new C(); }

    function testFuzz_property(address manager) public {
        vm.assume(manager != address(0));

        // The reference C disables its initializers in the constructor, so we initialize
        // its logic through a minimal delegatecall proxy whose address has no code and
        // whose fresh storage satisfies the initializer guard. The proxy IS C's logic
        // running on its own state.
        InitProxy proxy = new InitProxy(address(c));
        MockLRTConfig cfg = new MockLRTConfig();

        (bool okInit, ) = address(proxy).call(abi.encodeCall(C.initialize, (address(cfg))));
        assertTrue(okInit, "initialize must succeed on fresh proxy storage");

        vm.prank(manager);
        (bool okPause, ) = address(proxy).call(abi.encodeCall(C.pause, ()));
        assertTrue(okPause, "manager pause must succeed in the reference");

        // Universal rule: after a completed pause flow, paused() reflects the real state.
        (bool okView, bytes memory ret) = address(proxy).staticcall(abi.encodeCall(C.paused, ()));
        assertTrue(okView && abi.decode(ret, (bool)), "paused() must be true after a successful pause");
    }
}

/// Minimal EIP-1167-style delegatecall proxy so C's initializer can run
/// (address(this) has no code, storage is fresh).
contract InitProxy {
    address public immutable target;

    constructor(address t) {
        target = t;
    }

    fallback() external payable {
        (bool ok, bytes memory ret) = target.delegatecall(msg.data);
        assembly {
            returndatacopy(0, 0, returndatasize())
            switch ok
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}

