contract MockLRTConfig {
    function hasRole(bytes32, address) external pure returns (bool) { return true; }
    function getRoleAdmin(bytes32) external pure returns (bytes32) { return 0x00; }
    function grantRole(bytes32, address) external pure {}
    function revokeRole(bytes32, address) external pure {}
    function renounceRole(bytes32, address) external pure {}
    function rsETH() external pure returns (address) { return address(0); }
    function assetStrategy(address) external pure returns (address) { return address(0); }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function getLSTToken(bytes32) external pure returns (address) { return address(0); }
    function getContract(bytes32) external pure returns (address) { return address(0); }
    function getSupportedAssetList() external pure returns (address[] memory) {
        address[] memory a;
        return a;
    }
    function depositLimitByAsset(address) external pure returns (uint256) { return 0; }
}

