pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function testFuzz_property(address manager, address admin) public {
        vm.assume(manager != address(0));
        vm.assume(admin != address(0));
        vm.assume(manager != admin);

        // minimal config stub granting DEFAULT_ADMIN_ROLE to admin and MANAGER to manager
        ConfigStub cfg = new ConfigStub(manager, admin);

        c = new C();
        c.initialize(address(cfg));

        // manager pauses; in P this stores the paused state
        vm.prank(manager);
        c.pause();

        // rule: since pause() completed, the paused state is stored, so an admin
        // unpause() (guarded by whenPaused, which reads paused()) must NOT revert.
        bool ok;
        vm.prank(admin);
        try c.unpause() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract ConfigStub is ILRTConfig, IAccessControl {
    mapping(bytes32 => mapping(address => bool)) private roles;

    constructor(address manager, address admin) {
        roles[bytes32(0x00)][admin] = true;
        roles[keccak256("MANAGER")][manager] = true;
    }

    function hasRole(bytes32 role, address account) external view override returns (bool) {
        return roles[role][account];
    }

    function getRoleAdmin(bytes32) external pure override returns (bytes32) {
        return 0x00;
    }

    function grantRole(bytes32 role, address account) external override {
        roles[role][account] = true;
    }

    function revokeRole(bytes32 role, address account) external override {
        roles[role][account] = false;
    }

    function renounceRole(bytes32 role, address account) external override {
        roles[role][account] = false;
    }

    function rsETH() external pure override returns (address) {
        return address(this);
    }

    function assetStrategy(address) external pure override returns (address) {
        return address(0);
    }

    function isSupportedAsset(address) external pure override returns (bool) {
        return true;
    }

    function getLSTToken(bytes32) external pure override returns (address) {
        return address(0);
    }

    function getContract(bytes32) external pure override returns (address) {
        return address(this);
    }

    function getSupportedAssetList() external pure override returns (address[] memory) {
        return new address[](0);
    }

    function depositLimitByAsset(address) external pure override returns (uint256) {
        return 0;
    }
}

