pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address token;

    function setUp() public { c = new C(); }

    function testFuzz_property(address newX) public {
        vm.assume(newX != address(0));
        vm.assume(newX.code.length == 0);
        vm.assume(newX != address(c));

        MockConfig oldConfig = new MockConfig();
        MockToken tok = new MockToken();
        token = address(tok);

        c.initialize(address(oldConfig));

        vm.prank(address(0xA11CE));
        try c.updateLRTConfig(newX) { /* ignore */ } catch { /* ignore */ }

        // General rule: after a successful update to a codeless nonzero address X,
        // config-dependent reads route through X, so getAssetCurrentLimit(token)
        // must revert (no code at X to answer depositLimitByAsset).
        bool ok;
        try c.getAssetCurrentLimit(token) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}

contract MockConfig {
    function hasRole(bytes32, address) external pure returns (bool) { return true; }
    function isSupportedAsset(address) external pure returns (bool) { return true; }
    function depositLimitByAsset(address) external pure returns (uint256) { return 1; }
    function rsETH() external pure returns (address) { return address(this); }
    function getContract(bytes32) external pure returns (address) { return address(this); }
}

